extract_content_from_yaml <- function(skill_content) {
  """
    Extracts the line number where a Rmarkdown YAML frontmatter block ends,
    assuming it follows an '---' marker at the beginning of the vector.

    Args:
      skill_content: A character vector containing lines (after Yaml header removal in rmd).
                     Starts with "---" if there's any YAML metadata to extract.
                    Returns:
                      Integer line number where content_start should begin; returns 1L by default, 
                        unless the frontmatter marker indicates a later beginning.
    """  


  start <- 1L

  if (length(skill_content) > 0 && skill_content[1] == "---") {
    end_idx <- which(skill_content == "---") + 1L
    start <- min(start, end_idx - 2)
  }

  return(start)
}


